"use client";

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import type { Card, Folder, LibraryItem, LibrarySnapshot } from "../lib/library";

type LibraryResponse = { revision: number; snapshot: LibrarySnapshot; updatedAt: string };
type Device = { id: string; name: string; createdAt: string; lastUsedAt: string | null };
type MenuAction = { label: string; run: () => void; danger?: boolean; disabled?: boolean; separator?: boolean };
type MenuState = { x: number; y: number; actions: MenuAction[] } | null;
type DialogState = { title: string; value: string; placeholder?: string; save: (value: string) => void } | null;
type SortMode = "manual" | "title" | "created" | "modified";
type Preferences = { highlight: string; textColors: string[]; headingColors: string[] };

const uid = () => crypto.randomUUID();
const now = () => new Date().toISOString();
const defaultPreferences: Preferences = {
  highlight: "#FFD60A",
  textColors: ["#FF453A", "#FF9F0A", "#30D158", "#0A84FF", "#BF5AF2"],
  headingColors: ["#FF453A", "#FF9F0A", "#FFD60A", "#30D158", "#0A84FF", "#BF5AF2"],
};

function cleanMarkdown(value: string) {
  return value.replace(/!\[[^\]]*\]\([^)]*\)/g, "[Image]").replace(/\[([^\]]+)\]\([^)]*\)/g, "$1")
    .replace(/<span\s+style="color:#[0-9a-f]{6}">(.*?)<\/span>/gi, "$1").replace(/^(#{1,6}|>|[-+*]|\d+\.)\s+/gm, "")
    .replace(/\*\*|__|==|`{1,3}|\*/g, "").replace(/\s+/g, " ").trim();
}

function Icon({ name, color, className = "" }: { name: string; color?: string | null; className?: string }) {
  return <span aria-hidden className={`sf sf-${name} ${className}`} style={color ? { color } : undefined} />;
}

export default function FlashnotesWeb({ displayName }: { displayName: string }) {
  const [library, setLibrary] = useState<LibrarySnapshot | null>(null);
  const [revision, setRevision] = useState(0);
  const [selectedFolderId, setSelectedFolderId] = useState<string | null>(null);
  const [selectedItemId, setSelectedItemId] = useState<string | null>(null);
  const [openTabs, setOpenTabs] = useState<string[]>([]);
  const [expanded, setExpanded] = useState<Set<string>>(new Set());
  const [saving, setSaving] = useState<"saved" | "saving" | "offline">("saved");
  const [sidebarVisible, setSidebarVisible] = useState(true);
  const [searchOpen, setSearchOpen] = useState(false);
  const [commandOpen, setCommandOpen] = useState(false);
  const [trashOpen, setTrashOpen] = useState(false);
  const [devicesOpen, setDevicesOpen] = useState(false);
  const [reviewItem, setReviewItem] = useState<LibraryItem | null>(null);
  const [newMenu, setNewMenu] = useState(false);
  const [sortMenu, setSortMenu] = useState(false);
  const [menu, setMenu] = useState<MenuState>(null);
  const [dialog, setDialog] = useState<DialogState>(null);
  const [styleFolder, setStyleFolder] = useState<Folder | null>(null);
  const [history, setHistory] = useState<Array<{ folder: string | null; item: string | null }>>([]);
  const [historyIndex, setHistoryIndex] = useState(-1);
  const [sortPrefs, setSortPrefs] = useState<Record<string, { mode: SortMode; ascending: boolean }>>({});
  const [preferences, setPreferences] = useState<Preferences>(defaultPreferences);
  const currentRevision = useRef(0);
  const saveTimer = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => {
    try {
      const sort = localStorage.getItem("flashnotes.sort"); const prefs = localStorage.getItem("flashnotes.preferences");
      if (sort) setSortPrefs(JSON.parse(sort)); if (prefs) setPreferences({ ...defaultPreferences, ...JSON.parse(prefs) });
    } catch { /* use defaults */ }
  }, []);
  useEffect(() => { localStorage.setItem("flashnotes.sort", JSON.stringify(sortPrefs)); }, [sortPrefs]);
  useEffect(() => { localStorage.setItem("flashnotes.preferences", JSON.stringify(preferences)); }, [preferences]);

  useEffect(() => {
    let cancelled = false;
    const load = async () => {
      try {
        const response = await fetch("/api/library", { cache: "no-store" }); if (!response.ok) throw new Error();
        const data = await response.json() as LibraryResponse;
        if (cancelled || (currentRevision.current && data.revision <= currentRevision.current)) return;
        currentRevision.current = data.revision; setRevision(data.revision); setLibrary(data.snapshot); setSaving("saved");
        const active = data.snapshot.folders.filter(folder => !folder.trashedAt);
        setSelectedFolderId(current => active.some(folder => folder.id === current) ? current : active.find(folder => !folder.parentId)?.id ?? null);
        setExpanded(current => current.size ? current : new Set(active.map(folder => folder.id)));
      } catch { if (!cancelled) setSaving("offline"); }
    };
    void load(); const timer = window.setInterval(load, 4000); window.addEventListener("focus", load);
    return () => { cancelled = true; clearInterval(timer); window.removeEventListener("focus", load); };
  }, []);

  const persist = useCallback(async (snapshot: LibrarySnapshot) => {
    setSaving("saving");
    try {
      const response = await fetch("/api/library", { method: "PUT", headers: { "content-type": "application/json" }, body: JSON.stringify({ revision: currentRevision.current, snapshot }) });
      const data = await response.json() as LibraryResponse & { current?: LibraryResponse };
      if (response.status === 409 && data.current) { setLibrary(data.current.snapshot); currentRevision.current = data.current.revision; setRevision(data.current.revision); setSaving("saved"); return; }
      if (!response.ok) throw new Error(); currentRevision.current = data.revision; setRevision(data.revision); setSaving("saved");
    } catch { setSaving("offline"); }
  }, []);
  const updateLibrary = useCallback((change: (snapshot: LibrarySnapshot) => LibrarySnapshot) => {
    setLibrary(current => { if (!current) return current; const next = change(current); if (saveTimer.current) clearTimeout(saveTimer.current); saveTimer.current = setTimeout(() => persist(next), 500); return next; });
  }, [persist]);

  const folders = useMemo(() => (library?.folders ?? []).filter(folder => !folder.trashedAt), [library]);
  const items = useMemo(() => (library?.items ?? []).filter(item => !item.trashedAt && !library?.folders.find(folder => folder.id === item.folderId)?.trashedAt), [library]);
  const selectedFolder = folders.find(folder => folder.id === selectedFolderId) ?? null;
  const selectedItem = items.find(item => item.id === selectedItemId) ?? null;
  const tabs = openTabs.map(id => items.find(item => item.id === id)).filter(Boolean) as LibraryItem[];
  const roots = folders.filter(folder => !folder.parentId).sort((a, b) => a.sortIndex - b.sortIndex);
  const folderItems = selectedFolder ? sortContents(items.filter(item => item.folderId === selectedFolder.id), sortPrefs[selectedFolder.id]) : [];
  const childFolders = selectedFolder ? sortFolders(folders.filter(folder => folder.parentId === selectedFolder.id), sortPrefs[selectedFolder.id]) : [];
  const headingOutline = selectedItem?.kind === "note" ? headings(selectedItem.noteMarkdown) : [];

  const navigate = useCallback((folder: string | null, item: string | null, record = true) => {
    setSelectedFolderId(folder); setSelectedItemId(item);
    if (item) setOpenTabs(value => value.includes(item) ? value : [...value, item]);
    if (record) { const next = history.slice(0, historyIndex + 1).concat({ folder, item }); setHistory(next); setHistoryIndex(next.length - 1); }
  }, [history, historyIndex]);
  const openItem = (item: LibraryItem) => navigate(item.folderId, item.id);
  const closeTab = (id: string) => setOpenTabs(value => { const next = value.filter(valueId => valueId !== id); if (id === selectedItemId) navigate(selectedFolderId, next.at(-1) ?? null, false); return next; });
  const backForward = (delta: number) => { const index = historyIndex + delta; const target = history[index]; if (!target) return; setHistoryIndex(index); navigate(target.folder, target.item, false); };

  const updateFolder = (id: string, patch: Partial<Folder>) => updateLibrary(value => ({ ...value, folders: value.folders.map(folder => folder.id === id ? { ...folder, ...patch, modifiedAt: now() } : folder) }));
  const updateItem = (id: string, patch: Partial<LibraryItem>) => updateLibrary(value => ({ ...value, items: value.items.map(item => item.id === id ? { ...item, ...patch, modifiedAt: now() } : item) }));
  const createFolder = (parentId: string | null = null) => {
    const siblings = folders.filter(folder => folder.parentId === parentId); const folder: Folder = { id: uid(), name: parentId ? "New Subfolder" : "New Folder", sortIndex: siblings.length, createdAt: now(), modifiedAt: now(), favoriteAt: null, trashedAt: null, colorHex: null, symbolName: "folder.fill", parentId };
    updateLibrary(value => ({ ...value, folders: [...value.folders, folder] })); if (parentId) setExpanded(value => new Set(value).add(parentId)); navigate(folder.id, null); renameFolder(folder);
  };
  const createItem = (kind: "note" | "deck", folderId = selectedFolderId) => {
    if (!folderId) return; const item: LibraryItem = { id: uid(), title: kind === "note" ? "Untitled Note" : "Untitled Deck", kind, sortIndex: items.filter(value => value.folderId === folderId).length, noteMarkdown: "", createdAt: now(), modifiedAt: now(), favoriteAt: null, trashedAt: null, tags: [], linkedDeckId: null, folderId, cards: [] };
    updateLibrary(value => ({ ...value, items: [...value.items, item] })); openItem(item); renameItem(item);
  };
  const renameFolder = (folder: Folder) => setDialog({ title: "Rename Folder", value: folder.name, save: value => updateFolder(folder.id, { name: value }) });
  const renameItem = (item: LibraryItem) => setDialog({ title: "Rename Item", value: item.title, save: value => updateItem(item.id, { title: value }) });
  const editTags = (item: LibraryItem) => setDialog({ title: `Tags for “${item.title}”`, value: item.tags.join(", "), placeholder: "study, biology, exam", save: value => updateItem(item.id, { tags: value.split(",").map(tag => tag.trim()).filter(Boolean) }) });
  const duplicateItem = (item: LibraryItem) => updateLibrary(value => ({ ...value, items: [...value.items, { ...item, id: uid(), title: `${item.title} Copy`, sortIndex: items.filter(test => test.folderId === item.folderId).length, createdAt: now(), modifiedAt: now(), favoriteAt: null, cards: item.cards.map(card => ({ ...card, id: uid() })) }] }));
  const descendants = (folderId: string): string[] => [folderId, ...folders.filter(folder => folder.parentId === folderId).flatMap(folder => descendants(folder.id))];
  const trashFolder = (folder: Folder) => { const ids = new Set(descendants(folder.id)); const date = now(); updateLibrary(value => ({ ...value, folders: value.folders.map(test => ids.has(test.id) ? { ...test, trashedAt: date, modifiedAt: date } : test), items: value.items.map(item => item.folderId && ids.has(item.folderId) ? { ...item, trashedAt: date, modifiedAt: date } : item) })); navigate(folder.parentId, null); };
  const trashItem = (item: LibraryItem) => { updateItem(item.id, { trashedAt: now() }); setOpenTabs(value => value.filter(id => id !== item.id)); navigate(item.folderId, null); };
  const moveEntry = (payload: string, folderId: string) => { const [kind, id] = payload.split(":"); if (kind === "item") updateItem(id, { folderId }); else if (kind === "folder" && id !== folderId && !descendants(id).includes(folderId)) updateFolder(id, { parentId: folderId }); };

  const folderMenu = (folder: Folder): MenuAction[] => [
    { label: "New Subfolder", run: () => createFolder(folder.id) }, { label: "New Flashcard Deck", run: () => createItem("deck", folder.id) }, { label: "New Note", run: () => createItem("note", folder.id) },
    { label: "", separator: true, run: () => {} }, { label: "Rename", run: () => renameFolder(folder) }, { label: folder.favoriteAt ? "Remove from Favorites" : "Add to Favorites", run: () => updateFolder(folder.id, { favoriteAt: folder.favoriteAt ? null : now() }) }, { label: "Change Color & Symbol…", run: () => setStyleFolder(folder) },
    { label: "", separator: true, run: () => {} }, { label: "Move Up", run: () => moveSibling(folder, -1, folders, updateLibrary) }, { label: "Move Down", run: () => moveSibling(folder, 1, folders, updateLibrary) },
    { label: "", separator: true, run: () => {} }, { label: "Delete", danger: true, run: () => trashFolder(folder) },
  ];
  const itemMenu = (item: LibraryItem): MenuAction[] => [
    { label: "Open", run: () => openItem(item) }, { label: "Rename", run: () => renameItem(item) }, { label: "Duplicate", run: () => duplicateItem(item) }, { label: item.favoriteAt ? "Remove from Favorites" : "Add to Favorites", run: () => updateItem(item.id, { favoriteAt: item.favoriteAt ? null : now() }) }, { label: "Edit Tags…", run: () => editTags(item) }, { label: "", separator: true, run: () => {} }, { label: "Delete", danger: true, run: () => trashItem(item) },
  ];
  const showMenu = (event: React.MouseEvent, actions: MenuAction[]) => { event.preventDefault(); setMenu({ x: event.clientX, y: event.clientY, actions }); };

  useEffect(() => {
    const key = (event: KeyboardEvent) => {
      const command = event.metaKey || event.ctrlKey;
      if (command && event.shiftKey && event.key.toLowerCase() === "f") { event.preventDefault(); setSearchOpen(true); }
      if (command && event.key.toLowerCase() === "k") { event.preventDefault(); setCommandOpen(true); }
      if (command && event.key.toLowerCase() === "n") { event.preventDefault(); selectedItem?.kind === "deck" ? undefined : createItem("note"); }
      if (command && event.key.toLowerCase() === "w" && selectedItem) { event.preventDefault(); closeTab(selectedItem.id); }
      if (event.key === "Delete" && selectedItem) trashItem(selectedItem);
      if (event.key === "Escape") { setMenu(null); setNewMenu(false); setSortMenu(false); }
    };
    window.addEventListener("keydown", key); return () => window.removeEventListener("keydown", key);
  });

  if (!library) return <main className="loading"><Icon name="note" /><p>{saving === "offline" ? "Couldn’t reach your library." : "Opening your library…"}</p></main>;
  const favoriteFolders = folders.filter(folder => folder.favoriteAt).sort((a, b) => (b.favoriteAt ?? "").localeCompare(a.favoriteAt ?? "")).slice(0, 4);
  const favoriteItems = items.filter(item => item.favoriteAt).sort((a, b) => (b.favoriteAt ?? "").localeCompare(a.favoriteAt ?? "")).slice(0, 6);
  const recent = [...items].sort((a, b) => b.modifiedAt.localeCompare(a.modifiedAt)).slice(0, 5);

  return <main className={`app-shell ${sidebarVisible ? "" : "sidebar-hidden"}`} onClick={() => { setMenu(null); setNewMenu(false); setSortMenu(false); }}>
    <header className="topbar">
      <div className="toolbar-navigation">
        <button className="icon-button" onClick={event => { event.stopPropagation(); setSidebarVisible(value => !value); }} title="Show or Hide Sidebar"><Icon name="sidebar" /></button>
        <div className="history-buttons"><button className="icon-button" disabled={historyIndex <= 0} onClick={() => backForward(-1)}><Icon name="back" /></button><button className="icon-button" disabled={historyIndex >= history.length - 1} onClick={() => backForward(1)}><Icon name="forward" /></button></div>
        <button className="toolbar-button" onClick={() => selectedItem ? navigate(selectedFolderId, null) : navigate(selectedFolder?.parentId ?? selectedFolderId, null)} disabled={!selectedFolder}><Icon name="home" /><span>Home</span></button>
      </div>
      <div className="window-title">FlashNotes</div>
      <div className="toolbar-actions"><button className="sync-state" data-state={saving} title={`Cloud revision ${revision}`}><Icon name={saving === "saved" ? "cloud-ok" : saving === "saving" ? "sync" : "cloud-off"} /></button><button className="icon-button" onClick={() => setSearchOpen(true)} title="Search Library"><Icon name="search" /></button><div className="menu-anchor"><button className="toolbar-button" onClick={event => { event.stopPropagation(); setNewMenu(value => !value); }}><Icon name="plus" /><span>New</span></button>{newMenu && <PopupMenu actions={[{ label: "Top-Level Folder", run: () => createFolder() }, { label: "Subfolder", disabled: !selectedFolder, run: () => selectedFolder && createFolder(selectedFolder.id) }, { label: "", separator: true, run: () => {} }, { label: "Flashcard Deck", disabled: !selectedFolder, run: () => createItem("deck") }, { label: "Note", disabled: !selectedFolder, run: () => createItem("note") }]} />}</div><button className="icon-button" onClick={() => setDevicesOpen(true)} title="Web Sync"><Icon name="settings" /></button></div>
    </header>

    {sidebarVisible && <aside className="sidebar">
      <div className="sidebar-title">FlashNotes</div><div className="sidebar-scroll"><div className="sidebar-head"><span>LIBRARY</span><div><button title="Expand all" onClick={() => setExpanded(new Set(folders.map(folder => folder.id)))}><Icon name="expand" /></button><button title="Collapse all" onClick={() => setExpanded(new Set())}><Icon name="collapse" /></button></div></div>
      {(favoriteFolders.length > 0 || favoriteItems.length > 0) && <><div className="section-label">FAVORITES</div>{favoriteFolders.map(folder => <QuickRow key={folder.id} folder={folder} active={selectedFolderId === folder.id && !selectedItemId} onClick={() => navigate(folder.id, null)} onContextMenu={event => showMenu(event, folderMenu(folder))} />)}{favoriteItems.map(item => <QuickRow key={item.id} item={item} active={selectedItemId === item.id} onClick={() => openItem(item)} onContextMenu={event => showMenu(event, itemMenu(item))} />)}</>}
      {recent.length > 0 && <><div className="section-label">RECENT</div>{recent.map(item => <QuickRow key={item.id} item={item} active={selectedItemId === item.id} onClick={() => openItem(item)} onContextMenu={event => showMenu(event, itemMenu(item))} />)}</>}
      <div className="section-label">FOLDERS</div>{roots.map(folder => <FolderNode key={folder.id} folder={folder} folders={folders} items={items} expanded={expanded} setExpanded={setExpanded} selectedFolderId={selectedFolderId} selectedItemId={selectedItemId} openFolder={id => navigate(id, null)} openItem={openItem} showFolderMenu={(event, value) => showMenu(event, folderMenu(value))} showItemMenu={(event, value) => showMenu(event, itemMenu(value))} moveEntry={moveEntry} />)}</div>
      {selectedItem?.kind === "note" && <div className="outline-pane"><div className="outline-title"><Icon name="outline" /> Outline</div>{headingOutline.length ? headingOutline.map(heading => <button key={`${heading.level}-${heading.offset}`} style={{ paddingLeft: 12 + heading.level * 10 }} onClick={() => document.querySelector<HTMLElement>(".markdown-surface")?.focus()}><small>H{heading.level}</small>{heading.title}</button>) : <div className="outline-empty"><Icon name="text" /><b>No headings yet</b><span>Add headings with # to build your outline.</span></div>}</div>}
      <div className="sidebar-footer"><button onClick={() => createFolder()}><Icon name="folder-plus" /> New Folder</button><button onClick={() => setTrashOpen(true)} title="Trash"><Icon name="trash" /></button></div>
    </aside>}

    <section className="workspace"><Breadcrumb folder={selectedFolder} item={selectedItem} folders={folders} go={id => navigate(id, null)} /><div className="tab-strip">{tabs.map(item => <button key={item.id} className={item.id === selectedItemId ? "active" : ""} onClick={() => openItem(item)}><Icon name={item.kind} /> <span>{item.title}</span><i onClick={event => { event.stopPropagation(); closeTab(item.id); }}>×</i></button>)}</div><div className="workspace-content">
      {selectedItem?.kind === "note" ? <NoteEditor item={selectedItem} decks={items.filter(item => item.kind === "deck")} preferences={preferences} setPreferences={setPreferences} change={patch => updateItem(selectedItem.id, patch)} changeItem={updateItem} /> : selectedItem?.kind === "deck" ? <DeckEditor item={selectedItem} change={patch => updateItem(selectedItem.id, patch)} review={() => setReviewItem(selectedItem)} /> : selectedFolder ? <FolderHome folder={selectedFolder} items={folderItems} children={childFolders} displayName={displayName} create={createItem} openItem={openItem} openFolder={id => navigate(id, null)} showItemMenu={(event, item) => showMenu(event, itemMenu(item))} showFolderMenu={(event, folder) => showMenu(event, folderMenu(folder))} sort={sortPrefs[selectedFolder.id] ?? { mode: "manual", ascending: true }} setSort={value => setSortPrefs(current => ({ ...current, [selectedFolder.id]: value }))} sortOpen={sortMenu} setSortOpen={setSortMenu} /> : <LibraryEmpty create={() => createFolder()} />}
    </div></section>

    {menu && <div className="context-menu" style={{ left: Math.min(menu.x, innerWidth - 230), top: Math.min(menu.y, innerHeight - 320) }} onClick={event => event.stopPropagation()}><PopupMenu actions={menu.actions} /></div>}
    {dialog && <EditDialog state={dialog} close={() => setDialog(null)} />}{styleFolder && <FolderStyle folder={folders.find(folder => folder.id === styleFolder.id) ?? styleFolder} change={patch => updateFolder(styleFolder.id, patch)} close={() => setStyleFolder(null)} />}
    {searchOpen && <SearchPanel folders={folders} items={items} openFolder={id => { navigate(id, null); setSearchOpen(false); }} openItem={item => { openItem(item); setSearchOpen(false); }} close={() => setSearchOpen(false)} />}
    {commandOpen && <CommandPanel folders={folders} items={items} runFolder={id => { navigate(id, null); setCommandOpen(false); }} runItem={item => { openItem(item); setCommandOpen(false); }} newFolder={() => { createFolder(); setCommandOpen(false); }} trash={() => { setTrashOpen(true); setCommandOpen(false); }} close={() => setCommandOpen(false)} />}
    {trashOpen && <TrashPanel library={library} update={updateLibrary} close={() => setTrashOpen(false)} />}{devicesOpen && <DevicePanel close={() => setDevicesOpen(false)} />}{reviewItem && <ReviewModal item={reviewItem} close={() => setReviewItem(null)} />}
  </main>;
}

function QuickRow({ folder, item, active, onClick, onContextMenu }: { folder?: Folder; item?: LibraryItem; active: boolean; onClick: () => void; onContextMenu: (event: React.MouseEvent) => void }) { return <button className={`nav-row quick ${active ? "active" : ""}`} onClick={onClick} onContextMenu={onContextMenu}><Icon name={folder ? "folder" : item?.kind ?? "note"} color={folder?.colorHex} /><span>{folder?.name ?? item?.title}</span></button>; }

function FolderNode(props: { folder: Folder; folders: Folder[]; items: LibraryItem[]; expanded: Set<string>; setExpanded: React.Dispatch<React.SetStateAction<Set<string>>>; selectedFolderId: string | null; selectedItemId: string | null; openFolder: (id: string) => void; openItem: (item: LibraryItem) => void; showFolderMenu: (event: React.MouseEvent, folder: Folder) => void; showItemMenu: (event: React.MouseEvent, item: LibraryItem) => void; moveEntry: (payload: string, folderId: string) => void; depth?: number }) {
  const { folder, folders, items, expanded, setExpanded } = props; const depth = props.depth ?? 0; const children = folders.filter(value => value.parentId === folder.id).sort((a, b) => a.sortIndex - b.sortIndex); const contents = items.filter(item => item.folderId === folder.id).sort((a, b) => a.kind === b.kind ? a.sortIndex - b.sortIndex : a.kind === "note" ? -1 : 1); const open = expanded.has(folder.id); const count = contents.length + children.reduce((sum, child) => sum + props.items.filter(item => item.folderId === child.id).length, 0); const has = children.length + contents.length > 0;
  return <div className="tree-node"><button draggable onDragStart={event => event.dataTransfer.setData("text/plain", `folder:${folder.id}`)} onDragOver={event => event.preventDefault()} onDrop={event => { event.preventDefault(); props.moveEntry(event.dataTransfer.getData("text/plain"), folder.id); }} className={`nav-row folder-row ${props.selectedFolderId === folder.id && !props.selectedItemId ? "active" : ""}`} style={{ paddingLeft: 8 + depth * 16 }} onClick={() => { props.openFolder(folder.id); if (has) setExpanded(value => { const next = new Set(value); open ? next.delete(folder.id) : next.add(folder.id); return next; }); }} onContextMenu={event => props.showFolderMenu(event, folder)}><Icon name="chevron" className={open ? "open" : ""} /><Icon name="folder" color={folder.colorHex} /><span>{folder.name}</span>{count > 0 && <small>{count}</small>}</button>{open && <div>{children.map(child => <FolderNode key={child.id} {...props} folder={child} depth={depth + 1} />)}{contents.map(item => <button draggable onDragStart={event => event.dataTransfer.setData("text/plain", `item:${item.id}`)} key={item.id} className={`nav-row item-row ${props.selectedItemId === item.id ? "active" : ""}`} style={{ paddingLeft: 30 + (depth + 1) * 16 }} onClick={() => props.openItem(item)} onContextMenu={event => props.showItemMenu(event, item)}><Icon name={item.kind} /><span>{item.title}</span></button>)}</div>}</div>;
}

function Breadcrumb({ folder, item, folders, go }: { folder: Folder | null; item: LibraryItem | null; folders: Folder[]; go: (id: string) => void }) { const path: Folder[] = []; let current = folder; while (current) { path.unshift(current); current = folders.find(value => value.id === current?.parentId) ?? null; } return <div className="breadcrumb"><button onClick={() => path[0] && go(path[0].id)}><Icon name="home" /></button>{path.map(value => <span key={value.id}><i>›</i><button onClick={() => go(value.id)}>{value.name}</button></span>)}{item && <span><i>›</i><b><Icon name={item.kind} />{item.title}</b></span>}</div>; }

function FolderHome({ folder, items, children, displayName, create, openItem, openFolder, showItemMenu, showFolderMenu, sort, setSort, sortOpen, setSortOpen }: { folder: Folder; items: LibraryItem[]; children: Folder[]; displayName: string; create: (kind: "note" | "deck") => void; openItem: (item: LibraryItem) => void; openFolder: (id: string) => void; showItemMenu: (event: React.MouseEvent, item: LibraryItem) => void; showFolderMenu: (event: React.MouseEvent, folder: Folder) => void; sort: { mode: SortMode; ascending: boolean }; setSort: (value: { mode: SortMode; ascending: boolean }) => void; sortOpen: boolean; setSortOpen: (value: boolean) => void }) {
  const [createOpen, setCreateOpen] = useState(false);
  return <div className="folder-home"><div className="welcome-block"><Icon name="stack" /><h1>Jambo</h1><p>What would you like to study, {displayName.split(" ")[0]}?</p></div><div className="folder-heading"><div><div><h2>{folder.name}</h2><small>{children.length ? `${children.length} subfolder${children.length === 1 ? "" : "s"}` : ""}{children.length && items.length ? "  •  " : ""}{items.length ? `${items.length} item${items.length === 1 ? "" : "s"}` : !children.length ? "Empty folder" : ""}</small></div></div><div className="menu-anchor"><button className="toolbar-button" onClick={event => { event.stopPropagation(); setSortOpen(!sortOpen); }}><Icon name="sort" /></button>{sortOpen && <PopupMenu actions={(["manual", "title", "created", "modified"] as SortMode[]).map(mode => ({ label: `${sort.mode === mode ? "✓  " : ""}${mode === "manual" ? "Manual" : mode === "title" ? "Name" : mode === "created" ? "Date Created" : "Date Modified"}`, run: () => setSort({ ...sort, mode }) }) as MenuAction).concat(([{ label: "", separator: true, run: () => {} }, { label: sort.ascending ? "Descending" : "Ascending", run: () => setSort({ ...sort, ascending: !sort.ascending }) }]) as MenuAction[])} />}</div><div className="menu-anchor"><button className="toolbar-button" onClick={event => { event.stopPropagation(); setCreateOpen(!createOpen); }}><Icon name="plus" /> New</button>{createOpen && <PopupMenu actions={[{ label: "Flashcard Deck", run: () => create("deck") }, { label: "Note", run: () => create("note") }]} />}</div></div>
  {children.length > 0 && <><h3 className="content-label">FOLDERS</h3><div className="content-list">{children.map(child => <button key={child.id} onClick={() => openFolder(child.id)} onContextMenu={event => showFolderMenu(event, child)}><Icon name="folder" color={child.colorHex} /><div><b>{child.name}</b><p>Folder</p></div><span>›</span></button>)}</div></>}
  <h3 className="content-label">CONTENTS</h3>{items.length ? <div className="content-list">{items.map(item => <button key={item.id} onClick={() => openItem(item)} onContextMenu={event => showItemMenu(event, item)}><Icon name={item.kind} /><div><b>{item.title}</b><p>{item.kind === "deck" ? `${item.cards.length} cards` : cleanMarkdown(item.noteMarkdown) || "Empty note"}</p></div><small>{new Date(item.modifiedAt).toLocaleDateString(undefined, { month: "long", day: "numeric", year: "numeric" })}</small><span>›</span></button>)}</div> : <div className="folder-empty"><Icon name="note" /><h2>This folder is empty</h2><p>Create a note or deck to get started.</p><button className="primary-button" onClick={() => create("note")}>New Note</button></div>}<blockquote>“True friends stab you in the front.”<small>— Oscar Wilde</small></blockquote></div>;
}

function LibraryEmpty({ create }: { create: () => void }) { return <div className="library-empty"><div className="welcome-block"><Icon name="stack" /><h1>Jambo</h1></div><Icon name="stack" /><h2>Start your library</h2><p>Create a folder to begin organizing decks and notes.</p><button className="primary-button" onClick={create}>Create Folder</button></div>; }

function NoteEditor({ item, decks, preferences, setPreferences, change, changeItem }: { item: LibraryItem; decks: LibraryItem[]; preferences: Preferences; setPreferences: React.Dispatch<React.SetStateAction<Preferences>>; change: (patch: Partial<LibraryItem>) => void; changeItem: (id: string, patch: Partial<LibraryItem>) => void }) {
  const [headingMenu, setHeadingMenu] = useState(false); const [highlightMenu, setHighlightMenu] = useState(false); const [colorMenu, setColorMenu] = useState(false); const [deckMenu, setDeckMenu] = useState(false); const editor = useRef<HTMLTextAreaElement>(null);
  const format = (prefix: string, suffix = prefix, placeholder = "text") => { const node = editor.current; if (!node) return; const start = node.selectionStart; const end = node.selectionEnd; const selected = item.noteMarkdown.slice(start, end) || placeholder; const value = item.noteMarkdown.slice(0, start) + prefix + selected + suffix + item.noteMarkdown.slice(end); change({ noteMarkdown: value }); requestAnimationFrame(() => { node.focus(); node.setSelectionRange(start + prefix.length, start + prefix.length + selected.length); }); };
  const heading = (level: number) => { const node = editor.current; if (!node) return; const start = item.noteMarkdown.lastIndexOf("\n", node.selectionStart - 1) + 1; change({ noteMarkdown: item.noteMarkdown.slice(0, start) + "#".repeat(level) + " " + item.noteMarkdown.slice(start).replace(/^#{1,6}\s/, "") }); };
  const linkDeck = (id: string | null) => change({ linkedDeckId: id });
  useEffect(() => { const deck = decks.find(value => value.id === item.linkedDeckId); if (!deck) return; const pairs = item.noteMarkdown.split("\n").map(line => line.split("::")).filter(parts => parts.length > 1 && parts[0].trim() && parts.slice(1).join("::").trim()); const additions = pairs.filter(parts => !deck.cards.some(card => card.front === parts[0].trim() && card.back === parts.slice(1).join("::").trim())).map((parts, index) => ({ id: uid(), front: parts[0].trim(), back: parts.slice(1).join("::").trim(), sortIndex: deck.cards.length + index })); if (additions.length) changeItem(deck.id, { cards: [...deck.cards, ...additions] }); }, [item.noteMarkdown, item.linkedDeckId, decks, changeItem]);
  const words = cleanMarkdown(item.noteMarkdown).split(/\s+/).filter(Boolean).length;
  const download = (kind: "md" | "txt") => { const blob = new Blob([kind === "md" ? item.noteMarkdown : cleanMarkdown(item.noteMarkdown)], { type: "text/plain" }); const a = document.createElement("a"); a.href = URL.createObjectURL(blob); a.download = `${item.title || "Untitled Note"}.${kind}`; a.click(); URL.revokeObjectURL(a.href); };
  return <div className="editor note-editor"><div className="note-title-row"><input className="title-input" value={item.title} onChange={event => change({ title: event.target.value })} /></div><div className="formatbar"><div className="menu-anchor"><button onClick={event => { event.stopPropagation(); setHeadingMenu(!headingMenu); }}><Icon name="heading" /></button>{headingMenu && <PopupMenu actions={[1,2,3,4].map(level => ({ label: `Heading ${level}`, run: () => heading(level) }))} />}</div><i /><button title="Bold" onClick={() => format("**", "**", "bold text")}><b>B</b></button><button title="Italic" onClick={() => format("*", "*", "italic text")}><em>I</em></button><button title="Inline Code" onClick={() => format("`", "`", "code")}><Icon name="code" /></button><button title="Link" onClick={() => format("[", "](https://example.com)", "link text")}><Icon name="link" /></button><i />
  <div className="menu-anchor"><button onClick={event => { event.stopPropagation(); setHighlightMenu(!highlightMenu); }}><Icon name="highlight" /> Highlight</button>{highlightMenu && <Palette title="Highlight Color" colors={["#FFD60A", "#34C759", "#64D2FF", "#FF6482"]} choose={color => { setPreferences(value => ({ ...value, highlight: color })); format("==", "==", "highlighted text"); setHighlightMenu(false); }} />}</div>
  <div className="menu-anchor"><button onClick={event => { event.stopPropagation(); setColorMenu(!colorMenu); }}><Icon name="palette" /> Text Color</button>{colorMenu && <Palette title="Text Color" colors={preferences.textColors.concat(["#AC8E68", "#8E8E93", "#FFFFFF", "#000000"])} choose={color => { format(`<span style="color:${color}">`, "</span>", "colored text"); setColorMenu(false); }} />}</div><span />
  <div className="menu-anchor"><button onClick={event => { event.stopPropagation(); setDeckMenu(!deckMenu); }}><Icon name="deck" /> {decks.find(deck => deck.id === item.linkedDeckId)?.title ?? "Card Deck"}</button>{deckMenu && <PopupMenu actions={[{ label: `${!item.linkedDeckId ? "✓  " : ""}None`, run: () => linkDeck(null) }, ...decks.map(deck => ({ label: `${item.linkedDeckId === deck.id ? "✓  " : ""}${deck.title}`, run: () => linkDeck(deck.id) }))]} />}</div><div className="menu-anchor export-menu"><button><Icon name="export" /> Export</button><PopupMenu actions={[{ label: "Markdown", run: () => download("md") }, { label: "Plain Text", run: () => download("txt") }, { label: "PDF", run: () => window.print() }]} /></div></div>
  <div className="markdown-editor"><MarkdownPreview value={item.noteMarkdown} headingColors={preferences.headingColors} highlight={preferences.highlight} /><textarea ref={editor} className="markdown-input" value={item.noteMarkdown} onChange={event => change({ noteMarkdown: event.target.value })} onScroll={event => { const preview = event.currentTarget.previousElementSibling as HTMLElement; preview.scrollTop = event.currentTarget.scrollTop; preview.scrollLeft = event.currentTarget.scrollLeft; }} placeholder="Write in Markdown…" spellCheck /></div><div className="statusbar"><span>{words} words</span><span>{item.noteMarkdown.length} characters</span><span>{Math.max(1, Math.ceil(words / 220))} min read</span>{item.linkedDeckId && <><i /><Icon name="deck" /><span>{decks.find(deck => deck.id === item.linkedDeckId)?.title}</span><span className="tertiary">Use front :: back to add cards</span></>}<span className="status-spacer" /><label># <input value={item.tags.join(", ")} onChange={event => change({ tags: event.target.value.split(",").map(value => value.trim()).filter(Boolean) })} placeholder="tags" /></label></div></div>;
}

function MarkdownPreview({ value, headingColors, highlight }: { value: string; headingColors: string[]; highlight: string }) { return <div className="markdown-preview" aria-hidden>{value.split("\n").map((line, index) => { const match = line.match(/^(#{1,6})\s(.*)$/); const level = match?.[1].length ?? 0; return <div key={index} className={level ? `md-heading h${level}` : line.startsWith("> ") ? "md-quote" : "md-line"} style={level ? { color: headingColors[level - 1] } : undefined} dangerouslySetInnerHTML={{ __html: inlineMarkdown(match ? `${match[1]} ${match[2]}` : line || " ", highlight) }} />; })}</div>; }
function inlineMarkdown(raw: string, highlight: string) { let value = escapeHTML(raw); value = value.replace(/(&lt;span style=&quot;color:(#[0-9A-Fa-f]{6})&quot;&gt;)(.*?)(&lt;\/span&gt;)/g, '<span class="md-syntax">$1</span><span style="color:$2">$3</span><span class="md-syntax">$4</span>'); value = value.replace(/==(.+?)==/g, `<span class="md-syntax">==</span><mark style="background:${highlight}66">$1</mark><span class="md-syntax">==</span>`).replace(/\*\*(.+?)\*\*/g, '<span class="md-syntax">**</span><strong>$1</strong><span class="md-syntax">**</span>').replace(/`([^`]+)`/g, '<span class="md-syntax">`</span><code>$1</code><span class="md-syntax">`</span>').replace(/\[([^\]]+)\]\(([^)]+)\)/g, '<span class="md-link"><span class="md-syntax">[</span>$1<span class="md-syntax">]($2)</span></span>').replace(/^(#{1,6})\s/, '<span class="md-syntax">$1&nbsp;</span>'); return value; }
function escapeHTML(value: string) { return value.replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;").replaceAll('"', "&quot;"); }

function DeckEditor({ item, change, review }: { item: LibraryItem; change: (patch: Partial<LibraryItem>) => void; review: () => void }) { const [selected, setSelected] = useState(item.cards[0]?.id ?? null); const [cardMenu, setCardMenu] = useState<{ x: number; y: number; card: Card } | null>(null); const card = item.cards.find(value => value.id === selected) ?? item.cards[0]; const add = () => { const value = { id: uid(), front: "", back: "", sortIndex: item.cards.length }; change({ cards: [...item.cards, value] }); setSelected(value.id); }; const update = (patch: Partial<Card>) => card && change({ cards: item.cards.map(value => value.id === card.id ? { ...value, ...patch } : value) }); const duplicate = (source = card) => source && change({ cards: [...item.cards, { ...source, id: uid(), sortIndex: item.cards.length }] }); const remove = (source = card) => source && change({ cards: item.cards.filter(value => value.id !== source.id).map((value, index) => ({ ...value, sortIndex: index })) }); return <div className="editor deck-editor" onClick={() => setCardMenu(null)}><div className="deck-header"><input className="title-input" value={item.title} onChange={event => change({ title: event.target.value })} /><button className="primary-button" disabled={!item.cards.length} onClick={review}><Icon name="play" /> Review</button></div>{item.cards.length ? <div className="deck-workspace"><div className="card-rail"><div className="rail-title"><b>CARDS</b><span>{item.cards.length}</span></div>{item.cards.map((value, index) => <button key={value.id} className={value.id === card?.id ? "active" : ""} onClick={() => setSelected(value.id)} onContextMenu={event => { event.preventDefault(); event.stopPropagation(); setSelected(value.id); setCardMenu({ x: event.clientX, y: event.clientY, card: value }); }}><span>{index + 1}</span><div><b>{cleanMarkdown(value.front) || "Empty"}</b><small>{cleanMarkdown(value.back) || "Empty"}</small></div></button>)}<button className="add-card" onClick={add}><Icon name="plus" /> Add Card</button><div className="card-actions"><button onClick={() => duplicate()} title="Duplicate"><Icon name="duplicate" /></button><button onClick={() => remove()} title="Delete"><Icon name="trash" /></button></div></div><div className="card-fields"><label>FRONT<textarea value={card?.front ?? ""} onChange={event => update({ front: event.target.value })} /></label><hr/><label>BACK<textarea value={card?.back ?? ""} onChange={event => update({ back: event.target.value })} /></label></div></div> : <div className="folder-empty deck-empty"><Icon name="deck-plus" /><h2>Add your first card</h2><p>Create a front and back, then start reviewing.</p><button className="primary-button" onClick={add}>Add Card</button></div>}{cardMenu && <div className="context-menu" style={{ left: cardMenu.x, top: cardMenu.y }} onClick={event => event.stopPropagation()}><PopupMenu actions={[{ label: "Duplicate", icon: "duplicate", run: () => { duplicate(cardMenu.card); setCardMenu(null); } }, { separator: true }, { label: "Delete", icon: "trash", danger: true, run: () => { remove(cardMenu.card); setCardMenu(null); } }]} /></div>}</div>; }

function PopupMenu({ actions }: { actions: MenuAction[] }) { return <div className="popup-menu">{actions.map((action, index) => action.separator ? <hr key={index} /> : <button key={`${action.label}-${index}`} disabled={action.disabled} className={action.danger ? "danger" : ""} onClick={() => { if (!action.disabled) action.run(); }}>{action.label}</button>)}</div>; }
function Palette({ title, colors, choose }: { title: string; colors: string[]; choose: (color: string) => void }) { return <div className="palette-popover"><b>{title}</b><div>{colors.map(color => <button key={color} style={{ background: color }} onClick={() => choose(color)} aria-label={color} />)}</div></div>; }
function EditDialog({ state, close }: { state: NonNullable<DialogState>; close: () => void }) { const [value, setValue] = useState(state.value); const save = () => { if (!value.trim()) return; state.save(value.trim()); close(); }; return <div className="modal-backdrop" onMouseDown={close}><div className="edit-dialog" onMouseDown={event => event.stopPropagation()}><h2>{state.title}</h2><input autoFocus value={value} placeholder={state.placeholder} onChange={event => setValue(event.target.value)} onKeyDown={event => event.key === "Enter" && save()} /><div><button onClick={close}>Cancel</button><button className="primary-button" onClick={save}>Save</button></div></div></div>; }
function FolderStyle({ folder, change, close }: { folder: Folder; change: (patch: Partial<Folder>) => void; close: () => void }) { const colors: Array<string | null> = [null,"#0A84FF","#BF5AF2","#30D158","#FFD60A","#FF9F0A","#FF453A","#FF375F","#64D2FF","#8E8E93"]; const symbols = ["folder","book","graduation","brain","atom","flask","globe","music","palette","briefcase","star","heart"]; return <div className="modal-backdrop"><div className="style-dialog"><header><h2>Folder Appearance</h2><button onClick={close}>Done</button></header><input value={folder.name} onChange={event => change({ name: event.target.value })}/><b>SYMBOL</b><div className="symbol-grid">{symbols.map(symbol => <button key={symbol} className={folder.symbolName === symbol ? "selected" : ""} onClick={() => change({ symbolName: symbol })}><Icon name={symbol} /></button>)}</div><b>COLOR</b><div className="color-grid">{colors.map((color, index) => <button key={index} className={folder.colorHex === color ? "selected" : ""} style={{ background: color ?? "#8E8E93" }} onClick={() => change({ colorHex: color })} />)}</div></div></div>; }

function SearchPanel({ folders, items, openFolder, openItem, close }: { folders: Folder[]; items: LibraryItem[]; openFolder: (id: string) => void; openItem: (item: LibraryItem) => void; close: () => void }) { const [query, setQuery] = useState(""); const [scope, setScope] = useState("All"); const text = query.toLowerCase(); const foundFolders = scope !== "Notes" && scope !== "Decks" ? folders.filter(folder => folder.name.toLowerCase().includes(text)) : []; const foundItems = scope !== "Folders" ? items.filter(item => (scope === "All" || (scope === "Notes" && item.kind === "note") || (scope === "Decks" && item.kind === "deck")) && `${item.title} ${item.noteMarkdown} ${item.tags.join(" ")} ${item.cards.flatMap(card => [card.front, card.back]).join(" ")}`.toLowerCase().includes(text)) : []; return <div className="modal-backdrop"><div className="search-panel"><header><Icon name="search" /><input autoFocus placeholder="Search titles, notes, cards, and tags" value={query} onChange={event => setQuery(event.target.value)} /><select value={scope} onChange={event => setScope(event.target.value)}>{["All","Notes","Decks","Folders"].map(value => <option key={value}>{value}</option>)}</select><button onClick={close}>×</button></header><div className="search-results">{!query ? <div className="panel-empty"><Icon name="search" /><h2>Search your library</h2><p>Find folders, notes, deck titles, card text, and tags.</p></div> : <>{foundFolders.length > 0 && <h3>FOLDERS</h3>}{foundFolders.map(folder => <button key={folder.id} onClick={() => openFolder(folder.id)}><Icon name="folder" color={folder.colorHex}/><div><b>{folder.name}</b><small>Folder</small></div></button>)}{foundItems.length > 0 && <h3>CONTENT</h3>}{foundItems.map(item => <button key={item.id} onClick={() => openItem(item)}><Icon name={item.kind}/><div><b>{item.title}</b><small>{item.tags.map(tag => `#${tag}`).join(" ") || cleanMarkdown(item.noteMarkdown).slice(0,80)}</small></div></button>)}{!foundFolders.length && !foundItems.length && <div className="panel-empty"><h2>No results for “{query}”</h2></div>}</>}</div></div></div>; }
function CommandPanel({ folders, items, runFolder, runItem, newFolder, trash, close }: { folders: Folder[]; items: LibraryItem[]; runFolder: (id: string) => void; runItem: (item: LibraryItem) => void; newFolder: () => void; trash: () => void; close: () => void }) { const [query, setQuery] = useState(""); const entries = [{ label: "New Top-Level Folder", icon: "folder-plus", run: newFolder }, { label: "Open Trash", icon: "trash", run: trash }, ...folders.map(folder => ({ label: `Open ${folder.name}`, icon: "folder", run: () => runFolder(folder.id) })), ...items.map(item => ({ label: `Open ${item.title}`, icon: item.kind, run: () => runItem(item) }))].filter(entry => entry.label.toLowerCase().includes(query.toLowerCase())).slice(0,30); return <div className="modal-backdrop" onMouseDown={close}><div className="command-panel" onMouseDown={event => event.stopPropagation()}><header><Icon name="command"/><input autoFocus placeholder="Type a command or item name" value={query} onChange={event => setQuery(event.target.value)}/></header>{entries.map(entry => <button key={entry.label} onClick={entry.run}><Icon name={entry.icon}/>{entry.label}</button>)}</div></div>; }

function TrashPanel({ library, update, close }: { library: LibrarySnapshot; update: (change: (value: LibrarySnapshot) => LibrarySnapshot) => void; close: () => void }) { const folders = library.folders.filter(folder => folder.trashedAt && (!folder.parentId || !library.folders.find(value => value.id === folder.parentId)?.trashedAt)); const items = library.items.filter(item => item.trashedAt && !library.folders.find(folder => folder.id === item.folderId)?.trashedAt); const restoreFolder = (id: string) => { const child = (value: string): string[] => [value, ...library.folders.filter(folder => folder.parentId === value).flatMap(folder => child(folder.id))]; const ids = new Set(child(id)); update(value => ({ ...value, folders: value.folders.map(folder => ids.has(folder.id) ? { ...folder, trashedAt: null, modifiedAt: now() } : folder), items: value.items.map(item => item.folderId && ids.has(item.folderId) ? { ...item, trashedAt: null, modifiedAt: now() } : item) })); }; return <div className="modal-backdrop"><div className="trash-panel"><header><h2><Icon name="trash"/> Trash</h2><button onClick={close}>Done</button></header>{!folders.length && !items.length ? <div className="panel-empty"><Icon name="trash"/><h2>Trash is empty</h2><p>Deleted content can be restored from here.</p></div> : <div className="trash-list">{folders.length > 0 && <h3>FOLDERS</h3>}{folders.map(folder => <div key={folder.id}><Icon name="folder"/><b>{folder.name}</b><button onClick={() => restoreFolder(folder.id)}>Restore</button><button className="danger" onClick={() => update(value => ({ ...value, folders: value.folders.filter(test => test.id !== folder.id), items: value.items.filter(item => item.folderId !== folder.id) }))}>Delete Permanently</button></div>)}{items.length > 0 && <h3>NOTES AND DECKS</h3>}{items.map(item => <div key={item.id}><Icon name={item.kind}/><b>{item.title}</b><button onClick={() => update(value => ({ ...value, items: value.items.map(test => test.id === item.id ? { ...test, trashedAt: null, modifiedAt: now() } : test) }))}>Restore</button><button className="danger" onClick={() => update(value => ({ ...value, items: value.items.filter(test => test.id !== item.id) }))}>Delete Permanently</button></div>)}</div>}</div></div>; }
function ReviewModal({ item, close }: { item: LibraryItem; close: () => void }) { const [order, setOrder] = useState<"ordered"|"random">("ordered"); const [started, setStarted] = useState(false); const [cards, setCards] = useState(item.cards); const [index, setIndex] = useState(0); const [flipped, setFlipped] = useState(false); useEffect(() => { if (!started) return; const handleKey = (event: KeyboardEvent) => { if (event.key === "Escape") close(); if (event.key === " " || event.key === "ArrowRight") { event.preventDefault(); flipped ? (setIndex(value => value + 1), setFlipped(false)) : setFlipped(true); } if (event.key === "ArrowLeft" && index > 0) { setIndex(value => value - 1); setFlipped(false); } }; window.addEventListener("keydown", handleKey); return () => window.removeEventListener("keydown", handleKey); }, [started, flipped, index, close]); if (!started) return <div className="modal-backdrop"><div className="review-setup"><Icon name="deck"/><h2>Review {item.title}</h2><p>{item.cards.length} cards</p><select value={order} onChange={event => setOrder(event.target.value as "ordered"|"random")}><option value="ordered">Ordered</option><option value="random">Random</option></select><div><button onClick={close}>Cancel</button><button className="primary-button" onClick={() => { setCards(order === "random" ? [...item.cards].sort(() => Math.random() - .5) : item.cards); setStarted(true); }}>Start Review</button></div></div></div>; const card = cards[index]; const done = index >= cards.length; return <div className="review-full"><header><button onClick={close}><Icon name="home"/> Home</button><span>{item.title}</span><button onClick={() => { setIndex(0); setFlipped(false); }}><Icon name="restart"/> Restart</button></header>{done ? <div className="review-complete"><Icon name="check"/><h1>Review complete</h1><p>You reviewed {cards.length} cards.</p><button onClick={close}>Home</button><button className="primary-button" onClick={() => { setIndex(0); setFlipped(false); }}>Review Again</button></div> : <><div className="review-progress"><span>Card {index + 1} of {cards.length}</span><progress value={index + 1} max={cards.length}/></div><button className="review-card" onClick={() => setFlipped(value => !value)}><small>{flipped ? "BACK" : "FRONT"}</small><h2>{flipped ? card.back : card.front}</h2><p>{flipped ? "Press Space for next card" : "Press Space to reveal"}</p></button><button className="primary-button next-card" onClick={() => flipped ? (setIndex(value => value + 1), setFlipped(false)) : setFlipped(true)}>{flipped ? "Next Card" : "Reveal Answer"}</button></>}</div>; }
function DevicePanel({ close }: { close: () => void }) { const [devices, setDevices] = useState<Device[]>([]); const [token, setToken] = useState(""); const [copied, setCopied] = useState(false); const load = useCallback(() => fetch("/api/devices").then(response => response.json()).then(data => setDevices(data.devices ?? [])), []); useEffect(() => { void load(); }, [load]); const connect = async () => { const response = await fetch("/api/devices", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ name: "My Mac" }) }); const data = await response.json(); setToken(data.token); void load(); }; return <div className="modal-backdrop"><div className="device-panel"><button className="modal-close" onClick={close}>×</button><Icon name="sync"/><p className="eyebrow">WEB SYNC</p><h2>Connect FlashNotes on your Mac</h2><ol><li>Create and copy a private connection key below.</li><li>Open FlashNotes → Settings → Web Sync.</li><li>Paste the key and click Sync Now.</li></ol>{token ? <div className="token-box"><code>{token}</code><button onClick={() => { void navigator.clipboard.writeText(token); setCopied(true); }}>{copied ? "Copied" : "Copy key"}</button></div> : <button className="primary-button wide" onClick={connect}>Create connection key</button>}<div className="device-list"><h3>Connected Macs</h3>{devices.map(device => <div key={device.id}><Icon name="computer"/><p><b>{device.name}</b><small>{device.lastUsedAt ? `Last synced ${relativeDate(device.lastUsedAt)}` : "Waiting for first sync"}</small></p><button onClick={async () => { await fetch(`/api/devices?id=${encodeURIComponent(device.id)}`, { method: "DELETE" }); void load(); }}>Revoke</button></div>)}</div></div></div>; }

function headings(value: string) { let offset = 0; return value.split("\n").flatMap(line => { const match = line.match(/^(#{1,6})\s+(.+)/); const result = match ? [{ level: match[1].length, title: match[2], offset }] : []; offset += line.length + 1; return result; }); }
function sortContents(values: LibraryItem[], pref = { mode: "manual" as SortMode, ascending: true }) { return [...values].sort((a,b) => { let result = pref.mode === "title" ? a.title.localeCompare(b.title) : pref.mode === "created" ? a.createdAt.localeCompare(b.createdAt) : pref.mode === "modified" ? a.modifiedAt.localeCompare(b.modifiedAt) : a.kind !== b.kind ? (a.kind === "note" ? -1 : 1) : a.sortIndex - b.sortIndex; return pref.ascending ? result : -result; }); }
function sortFolders(values: Folder[], pref = { mode: "manual" as SortMode, ascending: true }) { return [...values].sort((a,b) => { const result = pref.mode === "title" ? a.name.localeCompare(b.name) : pref.mode === "created" ? a.createdAt.localeCompare(b.createdAt) : pref.mode === "modified" ? a.modifiedAt.localeCompare(b.modifiedAt) : a.sortIndex - b.sortIndex; return pref.ascending ? result : -result; }); }
function moveSibling(folder: Folder, offset: number, folders: Folder[], update: (change: (value: LibrarySnapshot) => LibrarySnapshot) => void) { const siblings = folders.filter(value => value.parentId === folder.parentId).sort((a,b) => a.sortIndex - b.sortIndex); const index = siblings.findIndex(value => value.id === folder.id); const target = index + offset; if (target < 0 || target >= siblings.length) return; [siblings[index], siblings[target]] = [siblings[target], siblings[index]]; const order = new Map(siblings.map((value, position) => [value.id, position])); update(value => ({ ...value, folders: value.folders.map(test => order.has(test.id) ? { ...test, sortIndex: order.get(test.id)!, modifiedAt: now() } : test) })); }
function relativeDate(iso: string) { const seconds = Math.max(0, (Date.now() - new Date(iso).getTime()) / 1000); return seconds < 60 ? "Now" : seconds < 3600 ? `${Math.floor(seconds/60)}m` : seconds < 86400 ? `${Math.floor(seconds/3600)}h` : `${Math.floor(seconds/86400)}d`; }
